import { test, expect, type Page } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../auth/user.json') });

const ANY_HINT =
  /כל הבריכה בתמונה|הקצה הרחוק של הבריכה|הרחיקו מעט את הטלפון|מוסתר|חשוך מדי|לא רואים מים/;

const scenarios = [
  { mock: 'lowCamera', hint: 'הקצה הרחוק של הבריכה לא בתמונה — הרימו מעט את המצלמה' },
  { mock: 'outOfFrame', hint: 'הרחיקו מעט את הטלפון' },
  { mock: 'blocked', hint: 'מוסתר' },
  { mock: 'unclear', hint: 'חשוך מדי — הוסיפו אור או חכו לאור יום' },
  { mock: 'noWater', hint: 'לא רואים מים' },
];

async function openCameraStep(page: Page, mock: string) {
  await page.goto(`/home?mock=${mock}`);
  await page.getByRole('button', { name: 'התחלת ניטור' }).click();
  await page.getByRole('button', { name: 'עוצמת צפצוף מקסימלית' }).click();
  await page.getByRole('button', { name: 'השמעה' }).click();
  await page.getByRole('button', { name: 'שמעתי' }).click();
  await page.getByRole('button', { name: 'המשך' }).click();
  await page.waitForURL(/\/monitor\/camera/);
}

test.describe('Наведение камеры', () => {
  test('Подсказки проблемных сценариев вверху картинки и блок «המשך» #7076cfab @iphone @prod-safe', async ({ context }) => {
    for (const { mock, hint } of scenarios) {
      // 1. Для каждого мока — в новой вкладке пройти подготовку до шага камеры.
      const page = await context.newPage();
      await openCameraStep(page, mock);

      // 2. Дождаться подсказки (timeout до 20 с).
      const hintLocator = page.getByText(hint);
      await expect(hintLocator, `mock=${mock}`).toBeVisible({ timeout: 20_000 });

      // В каждом сценарии ровно одна подсказка.
      await expect(page.getByText(ANY_HINT), `mock=${mock}`).toHaveCount(1);

      // 3. Сравнить положение подсказки и картинки-примера; нажать «המשך».
      const hintBox = await hintLocator.boundingBox();
      const continueButton = page.getByRole('button', { name: 'המשך' });
      const continueBox = await continueButton.boundingBox();
      const viewport = page.viewportSize();

      const imgBoxes = [];
      for (const img of await page.getByRole('img').all()) {
        const box = await img.boundingBox();
        if (box) imgBoxes.push(box);
      }
      const exampleImg = imgBoxes.reduce((a, b) => (b.width * b.height > a.width * a.height ? b : a));

      expect(hintBox, `mock=${mock}`).not.toBeNull();
      expect(continueBox, `mock=${mock}`).not.toBeNull();
      // в пределах viewport без прокрутки
      expect(hintBox!.y).toBeGreaterThanOrEqual(0);
      expect(hintBox!.y + hintBox!.height).toBeLessThanOrEqual(viewport!.height);
      // верх подсказки в верхней половине картинки-примера
      expect(hintBox!.y).toBeLessThan(exampleImg.y + exampleImg.height / 2);
      expect(hintBox!.y).toBeGreaterThanOrEqual(exampleImg.y);
      // выше «המשך»
      expect(hintBox!.y + hintBox!.height).toBeLessThanOrEqual(continueBox!.y);

      // «המשך» неактивна
      await expect(continueButton).toHaveAttribute('aria-disabled', 'true');
      await continueButton.click({ force: true });
      await expect(page).toHaveURL(/\/monitor\/camera/);

      await page.close();
    }
  });
});
